console.log("Delta number HEX: ", ((pvtKeyF - pvtKeyI) / BigInt(grateNumber)).toString(16))

let deltaGrate = (pvtKeyF - pvtKeyI) / BigInt(grateNumber);

//Chave inicial = Ponto relativa a primeira chave da serie
let pubKeyGen: bigint[] = keyGen.keys.eccnP(pvtKeyI, keyGen.keys.Gx, keyGen.keys.Gy);

console.log("pubKeyGenInt: ", pubKeyGen[0].toString(16))

//Ponto (delta * G)
let pubKeyGenDelta: bigint[] = keyGen.keys.eccnP(deltaGrate, keyGen.keys.Gx, keyGen.keys.Gy);

globalThis.addEventListener('message', (event) => {
  const { type, data, data2, data3, data4 } = event.data;
  switch (type) {
    case 0:
        pbKeyGrid();
        postMessage({ type: 0, result: pbkSet[10] });
        break;
    case 1:
        const stringResult = collisionSeekerStart(data, data2);;
        postMessage({ type: 1, result: stringResult });
        break;    
    case 2:
        const stringResultCont = collisionSeekerResume();
        postMessage({ type: 2, result: stringResultCont });
        break;        
    case 3:
        //continuação encomendada por usuário
        const stringResultCont2 = collisionSeekerResume(data, data2, data3, data4);
        //O type de retorno realmente é do tipo 2
        postMessage({ type: 2, result: stringResultCont2 });
        break;
    case 4:
        pbKeyGrid(data);
        postMessage({ type: 0, result: pbkSet[10] });
        break;            
    default:
        postMessage({ error: 'Unknown request type' });
  }
});

