//
//    Forma o grid de chaves publicas para busca por colisões
//    Grid de n chaves publicas derivadas de G, onde:
//    Pi = i x G, onde i varia de 0 a n + 2,
//    incluindo os pontos inicias e finais da serie  
//
/////////////////////////////////////////////////////////
function pbKeyGrid (pubkeyAlt?: string) {

    console.log("PBK: ", pubKeyCenter);
    ///////////////////////////////////////////////
    //new pubkey
    ///////////////////////////////////////////////
    if(pubkeyAlt !== undefined ){
        pubKeyCenter = pubkeyAlt;        
    }
    console.log("PBK: ", pubKeyCenter);
    ///////////////////////////////////////////////
    ///////////////////////////////////////////////


    pbkSet= new Array(grateNumber + 2);
    pbkSet [0] = pubKeyGen[0];
    
    //Soma o ponto Delta ao ponto de partida para chegar ao proximo ponto
    for(let i = 0; i < grateNumber; i++){

        pubKeyGen = keyGen.keys.addp(pubKeyGen[0], pubKeyGen[1], pubKeyGenDelta[0], pubKeyGenDelta[1]);
        
        //Chave inicial = Ponto relativa a primeira chave da serie
        pbkSet [i + 1] = pubKeyGen[0];
    
        //Linha de feedback no console
        if(i % ( 16 * cyclesToWait ) == 1)
            console.log("Point Creating: ", i)
    }
    
    //Utimo ponto da serie
    //Chave final = Ponto relativa a primeira ultima chave da serie
    pbkSet [grateNumber + 1] = keyGen.keys.eccnP(pvtKeyF, keyGen.keys.Gx, keyGen.keys.Gy)[0];

    console.log("pbkset: ", pbkSet)
};
