//
//Jesus is the Lord
//
//    Collision search, faz uma busca por colisões em "step" = s posições a partir do ponto de interesse
//    aqui designado de ponto central.
// 
//    Cada busca começa por:
// 
//          Pm = Pc + ((range + k) * 2 * s) x G;
//
//                          ou
//
//          Pm = Pc + ((-range - k) * 2 * s) x G;
//
//    A partir de Pm são realizadas s buscas para acima e abaixo deste ponto, cobrindo o range entre:
//    (Pm - s x G) e (Pm + s x G) incluindo Pm, contra todo o grid de testes;
//
//    Para (range + k) % 2 = 0 (par)
//
//    O range seguinte (range + 1) com P(m + 1) = Pm + ((1 + k) * 2 * s) x G
//    para k = 0, P(m + 1) = Pm + (2 * s) x G, o range coberto será:      
//
//    (P(m + 1) - s x G) e (P(m + 1) + s x G)
//    (Pm + (2 * s) x G - s x G) e (Pm + (2 * s) x G + s x G)
//
//    (Pm + s x G) e (Pm + (3 * s) x G), incluindo P(m + 1), contra todo o grid de testes;
//
//    Para (range + k) % 2 = 1 (impar)
//
//    O range seguinte (range + 1) com P(m + 1) = Pm + ((1 + k) * 2 * s) x G
//    para k = 0, P(m + 1) = Pm + (2 * s) x G, o range coberto será:
//
//    (P(m + 1) - (s - 1) x G) e (P(m + 1) + (s - 1) x G)
//    (Pm + (2 * s) x G - (s - 1) x G) e (Pm + (2 * s) x G + (s - 1) x G)
//
//    (Pm + s x G + G) e (Pm + (3 * s) x G - G), incluindo P(m + 1), contra todo o grid de testes;
//
/////////////////////////////////////////////////

let i_stt = 0;
let k_stt = 0;
let pubKeyAdd_stt: bigint[] = keyGen.keys.eccnP(1n, keyGen.keys.Gx, keyGen.keys.Gy);
let pubKeySub_stt: bigint[] = keyGen.keys.eccnP(1n, keyGen.keys.Gx, keyGen.keys.Gy);
let rangeCycles_stt: number = 0;
let rangeAmount_stt: number = 0;
     
let flag = false;
let grate = 0; 
let nonce = 0; 

/**
 * Função para iniciar a busca em força bruta de uma chave privada para uma chave publica
 * 
 * @param rangeAmount 
 * @param rangeCycles 
 * @returns 
 */
function collisionSeekerStart (rangeAmount: number, rangeCycles: number): string {

    let pointCenter: bigint[] = keyGen.pubKeyCompSECRev(pubKeyCenter);
    let pointToSearch: bigint[];

    flag = false; // necessário para testes

    for(let k = 0; k < rangeCycles && !flag; k++ ){

        if(rangeAmount > 0)
        {
            //Determina uma chave publica do tamanho (rangeAmount * 2 * step)
            pointToSearch = keyGen.keys.eccnP(BigInt(rangeAmount + k) * (2n * step), keyGen.keys.Gx, keyGen.keys.Gy);
            //Soma a chave de referencia a chave publica (rangeAmount * 2 * step) * G
            pointToSearch = keyGen.keys.addp(pointCenter[0], pointCenter[1], pointToSearch[0], pointToSearch[1]);
        }
        else if (rangeAmount < 0)
        {
            //Determina uma chave publica do tamanho (-1)*(rangeAmount * 2 * step)
            pointToSearch = keyGen.keys.eccnP(-1n * BigInt(rangeAmount - k) * (2n * step), keyGen.keys.Gx, keyGen.keys.Gy);
            //Substrai a chave de referencia a chave publica (rangeAmount * 2 * step) * G  
            pointToSearch = keyGen.keys.addp(pointCenter[0], pointCenter[1], pointToSearch[0], (keyGen.keys.p - pointToSearch[1]));
        }
        else
        {
            pointToSearch = pointCenter;
        }
                
        console.log("pointCenter: ", pointToSearch[0].toString(16));

        let pubKeyAdd: bigint[] = pointToSearch;
        let pubKeySub = pubKeyAdd;

        //Testando a soma/subtração de um unico ponto

        grate = 0; 
        nonce = 0; 

        console.log("point ADD 0: ", pubKeyAdd[0].toString(16));
        console.log("point SUB 0: ", pubKeySub[0].toString(16));

        //////////////////////////////////////////////////////////////
        //Partindo de 0 checa 2^20 para frente e 2^20 para trás
        //  a some do step deve ser 2x
        //Partindo de 1 checa 2^20 para frente e 2^20 para trás
        //////////////////////////////////////////////////////////////

        //Verifica o ponto central contra o grade de (4096 * 64) = 262144 elementos se houve colisão;
        for(let j = 0; (j < grateNumber + 2) && !flag; j++){

            if(pointToSearch[0] == pbkSet[j]){
                flag = true
                grate = j;
                nonce = 0;
                return("Cycle: " + (k + 1) + " Range: " + rangeAmount_stt + " Flag: " + flag + " Collision @: " + grate + " Nonce: " + nonce);
            }
        }

        /////////////////////////////////////////
        // Otimização do ultimo valor de step
        //  dependendo da paridade
        /////////////////////////////////////////
        let mod2 = BigInt(rangeAmount + k) % 2n;

        let s = step - mod2; // step para mod2 positivo
        if(mod2 < 0)
            s = step + mod2; // step para mod2 negativo
        /////////////////////////////////////////
        /////////////////////////////////////////

        //Analisa (2 * step) pontos contra toda a grade
        for(let i = 0; i < s && !flag; i ++){

            //Soma:
            pubKeyAdd = keyGen.keys.addp(pubKeyAdd[0], pubKeyAdd[1], keyGen.keys.Gx, keyGen.keys.Gy);
            //Subtração:
            pubKeySub = keyGen.keys.addp(pubKeySub[0], pubKeySub[1], keyGen.keys.Gx, (keyGen.keys.p - keyGen.keys.Gy));

            //Verifica na grade de (4096 * 64) = 262144 elementos se houve colisão;
            for(let j = 0; (j < grateNumber + 2) && !flag; j++){

                if(pubKeyAdd[0] == pbkSet[j]){
                    flag = true
                    grate = j;
                    nonce = i;
                    return("Cycle: " + (k + 1) + " Range: " + rangeAmount_stt + " Flag: " + flag + " Collision @: " + grate + " Nonce: " + nonce);
                }
                if(pubKeySub[0] == pbkSet[j]){
                    flag = true
                    grate = -j;
                    nonce = i;
                    return("Cycle: " + (k + 1) + " Range: " + rangeAmount_stt + " Flag: " + flag + " Collision @: " + grate + " Nonce: " + nonce);
                }
            }

            //Linha critica, mas necessário para feedback;
            //Interromper e levar para a UI:
            //Salvar estados e continuar de onde parou;
            if(i % cyclesToWait == 1)
            {
                i_stt = i;
                k_stt = k;
                pubKeyAdd_stt = pubKeyAdd;
                pubKeySub_stt = pubKeySub;
                rangeCycles_stt = rangeCycles;
                rangeAmount_stt = rangeAmount;
                    
                console.log("pbkSet: ", pbkSet[i % (grateNumber + 2)]);
                console.log("Searching: ", i)
                console.log("pointCenterAdd: ", pubKeyAdd);
                console.log("pointCenterSub: ", pubKeySub);
                console.log("Cycle: ", (k + 1))

                //A quantidade de bits da chave publica não quarda relação alguma com a quantidade de bits da chave privada
                return("Step: " + i  + " Cycle: " + (k + 1) + " pbkSet: " + pbkSet[i % (grateNumber + 2)] +  " pointAddX: " + pubKeyAdd[0] 
                    + " pointSubX: " + pubKeySub[0] );
            }
        }

        //tem que sair não imoporta do tamanho do cycle
        if(rangeAmount_stt == 0) 
            k = rangeCycles_stt;
    }

    console.log ("Flag: ", flag);
    console.log("Collision @: ", grate);
    console.log("Nonce: ", nonce);
    console.log("Range Cycles: ", rangeCycles);
    
    //Se chegou ao final
    return("Cycle: " + rangeCycles + " Range: " + rangeAmount + " Flag: " + flag + " Collision @: " + grate + " Nonce: " + nonce);
};
